    /// `DELETE /cluster/acme/plugins/{id}`
    ///
    /// Delete ACME plugin configuration.
    public struct DeleteClusterAcmePluginsById: PVEAPIRequest, Hashable {
        public typealias Response = EmptyResponse
        public static let method: HTTPMethod = .delete
        public static let pathTemplate = "/cluster/acme/plugins/{id}"
        public static let schemaName = "delete_plugin"

        /// Unique identifier for ACME plugin instance.
        ///
        /// Format: `pve-configid`.
        public var id: String

        public init(id: String) {
            self.id = id
        }

        public var path: String { PathBuilder.path("cluster", "acme", "plugins", id.parameterValue) }

        public var parameters: [(String, String)] { [] }
    }

    /// `GET /cluster/acme/tos`
    ///
    /// Retrieve ACME TermsOfService URL from CA. Deprecated, please use /cluster/acme/meta.
    public struct GetClusterAcmeTos: PVEAPIRequest, Hashable {
        public typealias Response = String
        public static let method: HTTPMethod = .get
        public static let pathTemplate = "/cluster/acme/tos"
        public static let schemaName = "get_tos"

        /// URL of ACME CA directory endpoint.
        ///
        /// Default: `https://acme-v02.api.letsencrypt.org/directory`.
        public var directory: String?

        public init() {
        }

        public var path: String { PathBuilder.path("cluster", "acme", "tos") }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            if let value = directory { result.append(("directory", value.parameterValue)) }
            return result
        }
    }
